#include <bits/stdc++.h>
using namespace std;
int main(int c, char** v) { ifstream in(v[1]), out(v[2]); int t; in >> t; while (t--) { int n; in >> n; set<pair<int,int>> e; for (int i = 0; i < n - 1; i++) { int a, b; in >> a >> b; e.insert({min(a, b), max(a, b)}); } int a, b, x, y; if (!(out >> a >> b >> x >> y)) return 1; if (!e.count({min(a, b), max(a, b)})) return 1; e.erase({min(a, b), max(a, b)}); if (x < 1 || y < 1 || x > n || y > n || x == y) return 1; if (!e.insert({min(x, y), max(x, y)}).second) return 1; vector<vector<int>> adj(n + 1); for (auto [p, q] : e) { adj[p].push_back(q); adj[q].push_back(p); } vector<int> order = {1}, par(n + 1, 0); par[1] = -1; vector<bool> seen(n + 1, false); seen[1] = true; for (size_t i = 0; i < order.size(); i++) for (int u : adj[order[i]]) if (!seen[u]) { seen[u] = true; par[u] = order[i]; order.push_back(u); } if ((int)order.size() != n) return 1; vector<int> sz(n + 1, 1), big(n + 1, 0); for (int i = n - 1; i > 0; i--) { sz[par[order[i]]] += sz[order[i]]; big[par[order[i]]] = max(big[par[order[i]]], sz[order[i]]); } int cnt = 0; for (int w = 1; w <= n; w++) if (max(big[w], n - sz[w]) * 2 <= n) cnt++; if (cnt != 1) return 1; } return 0; }
